function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 10) return 'grid needs 1 to 10 rows.';
  const n = grid[0].length;
  if (n < 1 || n > 10) return 'Each row needs 1 to 10 cells.';
  if (grid.some(row => row.length !== n)) return 'Every row must have the same length.';
  if (grid.some(row => row.some(v => !Number.isInteger(v) || v < 1 || v > 100))) return 'Each value is a whole number from 1 to 100.';
  return null;
}

