function maxScore(grid) {
  const m = grid.length;
  const rowsWith = new Map();
  for (let r = 0; r < m; r++) {
    for (const value of grid[r]) {
      rowsWith.set(value, (rowsWith.get(value) ?? 0) | (1 << r));
    }
  }

  let best = new Array(1 << m).fill(-1);
  best[0] = 0;
  for (const [value, rows] of rowsWith) {
    const next = best.slice();
    for (let mask = 0; mask < 1 << m; mask++) {
      if (best[mask] < 0) continue;
      for (let r = 0; r < m; r++) {
        const bit = 1 << r;
        if ((rows & bit) === 0 || (mask & bit) !== 0) continue;
        next[mask | bit] = Math.max(next[mask | bit], best[mask] + value);
      }
    }
    best = next;
  }
  return Math.max(...best);
}

