function maxScore(grid) {
  const used = new Set();
  // Each row either contributes nothing or one cell whose value no earlier row has taken.
  const choose = r => {
    if (r === grid.length) return 0;
    let best = choose(r + 1);
    for (const value of grid[r]) {
      if (used.has(value)) continue;
      used.add(value);
      best = Math.max(best, value + choose(r + 1));
      used.delete(value);
    }
    return best;
  };
  return choose(0);
}

