function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const m = size === 'large' ? 10 : 1 + pick(5);
  const n = size === 'large' ? 10 : 1 + pick(5);
  // Styles: any value; a narrow range that repeats values across rows; only high values;
  // or high values in the top third of the rows and a few small values everywhere else.
  const style = pick(4);
  const range = r => [[1, 100], [1, size === 'large' ? 12 : 3], [90, 100], r * 3 < m ? [95, 100] : [1, 4]][style];
  return [Array.from({ length: m }, (_, r) => {
    const [low, high] = range(r);
    return Array.from({ length: n }, () => low + pick(high - low + 1));
  })];
}
